\mathrm{NatTrans}_{\mathcal C,\mathcal D}(\eta:F\Rightarrow G)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall X,Y\in\operatorname{Ob}\mathcal C)
(\forall f\in\operatorname{Hom}_{\mathcal C}(X,Y))\\
Gf\circ\eta_X=\eta_Y\circ Ff
\end{gathered}&\mathrm{NatComponents}_{\mathcal C,\mathcal D}(\eta;F,G),\\
\bot&\neg\mathrm{NatComponents}_{\mathcal C,\mathcal D}(\eta;F,G).
\end{cases}

\mathrm{NatIso}_{\mathcal C,\mathcal D}(\eta:F\Rightarrow G)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall X\in\operatorname{Ob}\mathcal C)
(\exists h\in\operatorname{Hom}_{\mathcal D}(GX,FX))\\
h\circ\eta_X=\operatorname{id}_{FX}\land\eta_X\circ h=\operatorname{id}_{GX}
\end{gathered}&\mathrm{NatTrans}_{\mathcal C,\mathcal D}(\eta:F\Rightarrow G),\\
\bot&\neg\mathrm{NatTrans}_{\mathcal C,\mathcal D}(\eta:F\Rightarrow G).
\end{cases}

\operatorname{Fun}(\mathcal C,\mathcal D)\coloneqq
\left\{F\in
(\operatorname{Ob}\mathcal D)^{\operatorname{Ob}\mathcal C}
\times(\operatorname{Mor}\mathcal D)^{\operatorname{Mor}\mathcal C}
\ \middle|\ \mathrm{Functor}(F,\mathcal C,\mathcal D)\right\}.

\mathrm{EquivFunctor}(F,\mathcal C,\mathcal D)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\exists H\in\operatorname{Fun}(\mathcal D,\mathcal C))\\
\left(\exists\alpha\in\prod_{X\in\operatorname{Ob}\mathcal C}
\mathcal C(X,(H\circ F)X)\right)
\left(\exists\beta\in\prod_{Y\in\operatorname{Ob}\mathcal D}
\mathcal D((F\circ H)Y,Y)\right)\\
\Bigl[\mathrm{NatIso}_{\mathcal C,\mathcal C}
(\alpha:\operatorname{Id}_{\mathcal C}\Rightarrow H\circ F)\\
\land\mathrm{NatIso}_{\mathcal D,\mathcal D}
(\beta:F\circ H\Rightarrow\operatorname{Id}_{\mathcal D})\Bigr]
\end{gathered}&F\in\operatorname{Fun}(\mathcal C,\mathcal D),\\
\bot&F\notin\operatorname{Fun}(\mathcal C,\mathcal D).
\end{cases}

\mathrm{IsoFunctor}(F,\mathcal C,\mathcal D)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\exists H\in\operatorname{Fun}(\mathcal D,\mathcal C))\\
H\circ F=\operatorname{Id}_{\mathcal C}\land F\circ H=\operatorname{Id}_{\mathcal D}
\end{gathered}&F\in\operatorname{Fun}(\mathcal C,\mathcal D),\\
\bot&F\notin\operatorname{Fun}(\mathcal C,\mathcal D).
\end{cases}
